package api_test

// Integration tests of the scenario routes (T-028) through the whole
// stack: the handler cmd/api serves as the plain API login, AI scenarios
// generated by the job loop over the fake provider and approved over HTTP,
// people's scenarios saved over HTTP (TEST-003, TEST-007, TEST-008,
// TEST-009 for scenarios). Without GEMINUS_TEST_DATABASE_URL they skip
// (NOT RUN).

import (
	"strings"
	"testing"

	"github.com/kcl1104/geminus/internal/ids"
	"github.com/kcl1104/geminus/internal/tenant"
)

type scenarioBodyView struct {
	ID               string  `json:"id"`
	OrganizationID   string  `json:"organization_id"`
	ModelID          string  `json:"model_id"`
	BaseVersionID    string  `json:"base_version_id"`
	Name             string  `json:"name"`
	PatchHash        string  `json:"patch_hash"`
	SourceProposalID *string `json:"source_proposal_id"`
	CreatedBy        string  `json:"created_by"`
}

type scenarioPage struct {
	Items      []scenarioBodyView `json:"items"`
	NextCursor *string            `json:"next_cursor"`
}

func (e *env) saveScenario(subject, org, version, key, body string) resp {
	h := map[string]string{}
	if key != "" {
		h["Idempotency-Key"] = key
	}
	return e.do("POST", "/v1/model-versions/"+version+"/scenarios", subject, org, h, body)
}

const sixRunners = `{"name":"Six CI runners","patch":[{"op":"test","path":"/resources/1/id","value":"ci_runner"},{"op":"replace","path":"/resources/1/capacity","value":6}]}`

// TEST-008, REQ-010, AI_SPEC §7 (the scenario half of the closed loop): an
// AI scenario, approved, and a person's scenario on the same version: both
// read and listed in scenario.schema.json, told apart by
// source_proposal_id; neither creates a version or queues anything; only
// the person's own createSimulation with the scenario_id queues a run.
func TestScenarioClosedLoop(t *testing.T) {
	e := setupProposals(t)
	editor, viewer := e.a.Members[tenant.Editor], e.a.Members[tenant.Viewer]
	m := e.newModel(t)
	v := m.LatestVersion.ID
	versions := func() int { return e.count(`SELECT count(*) FROM twin.model_versions WHERE model_id=$1`, m.ID) }
	queued := func() int {
		return e.count(`SELECT count(*) FROM twin.jobs WHERE organization_id=$1 AND type='simulation'`, e.a.ID)
	}
	before := versions()

	p := e.readyOver(t, m.ID, v, "scenario", "What if there were 8 runners?", eightRunners)
	r := e.decide(editor.Subject, e.a.ID, p.ProposalID, "approve", "scn-loop-0001", `{"expected_base_version_id":"`+v+`"}`)
	if r.status != 201 {
		t.Fatalf("approve: %d %s", r.status, r.body)
	}
	a := decode[approvalBody](t, r)
	if a.Mode != "scenario" || a.ScenarioID == "" || a.NewVersionID != "" {
		t.Fatalf("%s", r.body)
	}
	got := e.do("GET", "/v1/scenarios/"+a.ScenarioID, viewer.Subject, e.a.ID, nil, "")
	if got.status != 200 {
		t.Fatalf("get the AI scenario: %d %s", got.status, got.body)
	}
	valid(t, got, "scenario.schema.json")
	ai := decode[scenarioBodyView](t, got)
	if ai.SourceProposalID == nil || *ai.SourceProposalID != p.ProposalID || ai.BaseVersionID != v || ai.PatchHash != *p.PatchHash ||
		ai.Name != "Try 8 CI runners." || ai.CreatedBy != editor.UserID {
		t.Errorf("the AI scenario %s", got.body)
	}
	if !strings.Contains(string(got.body), `"patch":`+string(p.Changes)) {
		t.Errorf("the AI scenario's patch is not the proposal's: %s, %s", got.body, p.Changes)
	}

	r = e.saveScenario(editor.Subject, e.a.ID, v, "scn-loop-0002", sixRunners)
	if r.status != 201 {
		t.Fatalf("save: %d %s", r.status, r.body)
	}
	valid(t, r, "scenario.schema.json")
	manual := decode[scenarioBodyView](t, r)
	if manual.SourceProposalID != nil || manual.BaseVersionID != v || manual.CreatedBy != editor.UserID || manual.Name != "Six CI runners" {
		t.Errorf("the person's scenario %s", r.body)
	}
	if again := e.saveScenario(editor.Subject, e.a.ID, v, "scn-loop-0002", sixRunners); again.status != 201 || string(again.body) != string(r.body) {
		t.Errorf("replay: %d %s", again.status, again.body)
	}

	list := e.do("GET", "/v1/model-versions/"+v+"/scenarios", viewer.Subject, e.a.ID, nil, "")
	if list.status != 200 {
		t.Fatalf("list: %d %s", list.status, list.body)
	}
	valid(t, list, "http.schema.json#/$defs/Scenarios")
	page := decode[scenarioPage](t, list)
	if len(page.Items) != 2 || page.Items[0].ID != ai.ID || page.Items[1].ID != manual.ID || page.NextCursor != nil {
		t.Errorf("the version's scenarios %s", list.body)
	}
	one := e.do("GET", "/v1/model-versions/"+v+"/scenarios?limit=1", viewer.Subject, e.a.ID, nil, "")
	first := decode[scenarioPage](t, one)
	if len(first.Items) != 1 || first.NextCursor == nil {
		t.Fatalf("a page of one: %s", one.body)
	}
	rest := e.do("GET", "/v1/model-versions/"+v+"/scenarios?limit=1&cursor="+*first.NextCursor, viewer.Subject, e.a.ID, nil, "")
	if p := decode[scenarioPage](t, rest); rest.status != 200 || len(p.Items) != 1 || p.Items[0].ID != manual.ID || p.NextCursor != nil {
		t.Errorf("the next page: %d %s", rest.status, rest.body)
	}

	if n := versions(); n != before {
		t.Errorf("scenarios made %d versions out of %d", n, before)
	}
	if n := queued(); n != 0 {
		t.Errorf("scenarios queued %d runs", n)
	}
	// The person runs the scenario: now, and only now, a run is queued.
	run := e.do("POST", "/v1/simulations", editor.Subject, e.a.ID, map[string]string{"Idempotency-Key": "scn-loop-0003"},
		runRequest(v, 1, "none", map[string]any{"scenario_patch": nil, "scenario_id": manual.ID}))
	if run.status != 202 {
		t.Fatalf("run the scenario: %d %s", run.status, run.body)
	}
	if n := queued(); n != 1 {
		t.Errorf("%d runs queued by one request", n)
	}
	if n := e.count(`SELECT count(*) FROM twin.simulation_runs WHERE organization_id=$1 AND scenario_id=$2 AND model_version_id=$3`,
		e.a.ID, manual.ID, v); n != 1 {
		t.Errorf("%d runs of the scenario", n)
	}
}

// TEST-009 for scenarios: owners and editors save, viewers read; other
// organizations and strangers get 404; an unknown identity 403; no token
// 401.
func TestScenarioRoleMatrix(t *testing.T) {
	e := setup(t)
	owner, editor, viewer := e.a.Members[tenant.Owner], e.a.Members[tenant.Editor], e.a.Members[tenant.Viewer]
	outsider := e.b.Members[tenant.Owner]
	m := e.newModel(t)
	v := m.LatestVersion.ID
	for i, c := range []struct {
		name, subject, org string
		status             int
		code               string
	}{
		{"owner", owner.Subject, e.a.ID, 201, ""},
		{"editor", editor.Subject, e.a.ID, 201, ""},
		{"viewer", viewer.Subject, e.a.ID, 403, "FORBIDDEN"},
		{"member of another organization", outsider.Subject, e.a.ID, 404, "NOT_FOUND"},
		{"another organization's version", outsider.Subject, e.b.ID, 404, "NOT_FOUND"},
		{"identity without a user", "sub-nobody", e.a.ID, 403, "FORBIDDEN"},
		{"no token", "", e.a.ID, 401, "UNAUTHENTICATED"},
	} {
		r := e.saveScenario(c.subject, c.org, v, "key-scn-role-"+string(rune('a'+i)), sixRunners)
		if r.status != c.status || (c.code != "" && code(t, r) != c.code) {
			t.Errorf("save, %s: %d %s", c.name, r.status, r.body)
		}
	}
	created := decode[scenarioPage](t, e.do("GET", "/v1/model-versions/"+v+"/scenarios", viewer.Subject, e.a.ID, nil, ""))
	if len(created.Items) != 2 {
		t.Fatalf("%d scenarios, want the owner's and the editor's", len(created.Items))
	}
	id := created.Items[0].ID
	for _, s := range []string{owner.Subject, editor.Subject, viewer.Subject} {
		if r := e.do("GET", "/v1/scenarios/"+id, s, e.a.ID, nil, ""); r.status != 200 {
			t.Errorf("get as a member: %d %s", r.status, r.body)
		}
	}
	for name, c := range map[string][2]string{
		"other org's member in its own org": {outsider.Subject, e.b.ID},
		"other org's member naming a":       {outsider.Subject, e.a.ID},
	} {
		for _, path := range []string{"/v1/scenarios/" + id, "/v1/model-versions/" + v + "/scenarios"} {
			if r := e.do("GET", path, c[0], c[1], nil, ""); r.status != 404 || code(t, r) != "NOT_FOUND" {
				t.Errorf("%s, %s: %d %s", path, name, r.status, r.body)
			}
		}
	}
	if n := e.count(`SELECT count(*) FROM twin.scenarios WHERE organization_id=$1`, e.b.ID); n != 0 {
		t.Errorf("%d scenarios in b", n)
	}
}

// The request's own checks come first (path 400, key 400, media type 415,
// body 400/413/422) and each refusal is the contract's error with its
// JSON Pointer and request ID; refused requests store nothing.
func TestScenarioRequestRefusals(t *testing.T) {
	e := setup(t)
	editor := e.a.Members[tenant.Editor]
	m := e.newModel(t)
	v := m.LatestVersion.ID
	for i, c := range []struct {
		name, path, key, contentType, body string
		status                             int
		code, pointer                      string
	}{
		{"a model ID as the version", "/v1/model-versions/" + m.ID + "/scenarios", "k", "", sixRunners, 400, "INVALID_REQUEST", ""},
		{"no Idempotency-Key", "", "-", "", sixRunners, 400, "IDEMPOTENCY_KEY_REQUIRED", ""},
		{"text/plain", "", "k", "text/plain", sixRunners, 415, "UNSUPPORTED_MEDIA_TYPE", ""},
		{"malformed JSON", "", "k", "", `{"name":`, 400, "INVALID_REQUEST", ""},
		{"no patch", "", "k", "", `{"name":"x"}`, 422, "REQUEST_VALIDATION_FAILED", ""},
		{"the base in the body", "", "k", "", `{"name":"x","patch":[],"base_version_id":"` + v + `"}`, 422, "REQUEST_VALIDATION_FAILED", ""},
		{"a source proposal", "", "k", "", `{"name":"x","patch":[],"source_proposal_id":"` + ids.New("aip") + `"}`, 422, "REQUEST_VALIDATION_FAILED", ""},
		{"an empty name", "", "k", "", `{"name":"","patch":[]}`, 422, "REQUEST_VALIDATION_FAILED", "/name"},
		{"a name of white space", "", "k", "", `{"name":"   ","patch":[]}`, 422, "REQUEST_VALIDATION_FAILED", "/name"},
		{"U+0000 in the name", "", "k", "", `{"name":"a\u0000b","patch":[]}`, 422, "REQUEST_VALIDATION_FAILED", "/name"},
		{"move", "", "k", "", `{"name":"x","patch":[{"op":"move","from":"/resources/1","path":"/resources/0"}]}`, 422, "REQUEST_VALIDATION_FAILED", ""},
		{"removing a node", "", "k", "", `{"name":"x","patch":[{"op":"test","path":"/nodes/5/id","value":"ci_rework"},{"op":"remove","path":"/nodes/5"}]}`,
			422, "MODEL_VALIDATION_FAILED", "/patch/1/path"},
		{"an invalid model", "", "k", "", `{"name":"x","patch":[{"op":"test","path":"/flows/3/id","value":"f_pass"},{"op":"replace","path":"/flows/3/routing/probability","value":0.5}]}`,
			422, "MODEL_VALIDATION_FAILED", "/nodes/3"},
		{"no such version", "/v1/model-versions/" + ids.New("mv") + "/scenarios", "k", "", sixRunners, 404, "NOT_FOUND", ""},
	} {
		path := c.path
		if path == "" {
			path = "/v1/model-versions/" + v + "/scenarios"
		}
		h := map[string]string{}
		switch c.key {
		case "-":
		default:
			h["Idempotency-Key"] = "key-scn-bad-" + string(rune('a'+i))
		}
		if c.contentType != "" {
			h["Content-Type"] = c.contentType
		}
		r := e.do("POST", path, editor.Subject, e.a.ID, h, c.body)
		if r.status != c.status || code(t, r) != c.code {
			t.Errorf("%s: %d %s", c.name, r.status, r.body)
			continue
		}
		if c.pointer != "" && !strings.Contains(string(r.body), `"path":"`+c.pointer+`"`) {
			t.Errorf("%s: no detail at %s: %s", c.name, c.pointer, r.body)
		}
	}
	if r := e.saveScenario(editor.Subject, e.a.ID, v, "key-scn-bad-x", sixRunners); r.status != 201 {
		t.Fatalf("%d %s", r.status, r.body)
	}
	if r := e.saveScenario(editor.Subject, e.a.ID, v, "key-scn-bad-x", `{"name":"Another","patch":[]}`); r.status != 409 || code(t, r) != "IDEMPOTENCY_KEY_CONFLICT" {
		t.Errorf("the key with another body: %d %s", r.status, r.body)
	}
	if r := e.do("GET", "/v1/scenarios/"+ids.New("scn"), editor.Subject, e.a.ID, nil, ""); r.status != 404 || code(t, r) != "NOT_FOUND" {
		t.Errorf("no such scenario: %d %s", r.status, r.body)
	}
	if r := e.do("GET", "/v1/scenarios/"+v, editor.Subject, e.a.ID, nil, ""); r.status != 400 || code(t, r) != "INVALID_REQUEST" {
		t.Errorf("a version ID as the scenario: %d %s", r.status, r.body)
	}
	if r := e.do("GET", "/v1/model-versions/"+v+"/scenarios?cursor=bm90", editor.Subject, e.a.ID, nil, ""); r.status != 400 || code(t, r) != "INVALID_REQUEST" {
		t.Errorf("a cursor the list did not issue: %d %s", r.status, r.body)
	}
	if n := e.count(`SELECT count(*) FROM twin.scenarios WHERE organization_id=$1`, e.a.ID); n != 1 {
		t.Errorf("%d scenarios, want the one valid request's", n)
	}
}
